const SPEC_DONE_SCROLL_SELECTOR = '.spec-done-scroll[data-overlay-scroll-body="true"]';

function getSpecDoneScrollElement() {
  if (typeof document === 'undefined') return null;
  return document.querySelector(SPEC_DONE_SCROLL_SELECTOR);
}

function captureSpecDoneScrollSnapshot() {
  const scrollElement = getSpecDoneScrollElement();
  if (!scrollElement) return null;

  return {
    scrollTop: scrollElement.scrollTop,
    scrollLeft: scrollElement.scrollLeft,
  };
}

function scheduleSpecDoneScrollRestore(snapshot) {
  if (!snapshot) return;

  const restore = () => {
    const scrollElement = getSpecDoneScrollElement();
    if (!scrollElement) return;

    scrollElement.scrollTop = snapshot.scrollTop;
    scrollElement.scrollLeft = snapshot.scrollLeft ?? 0;
  };

  if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(() => requestAnimationFrame(restore));
    return;
  }

  setTimeout(restore, 0);
}

function clearDocumentTextSelection() {
  if (typeof window === 'undefined') return;
  const selection = window.getSelection?.();
  if (selection && typeof selection.removeAllRanges === 'function') {
    selection.removeAllRanges();
  }

  const activeElement = document.activeElement;
  if (
    activeElement instanceof HTMLTextAreaElement
    || activeElement instanceof HTMLInputElement
  ) {
    const caretPosition = activeElement.selectionEnd ?? activeElement.selectionStart ?? 0;
    activeElement.setSelectionRange(caretPosition, caretPosition);
  }
}

function FinalToolbarSessionPresetIcon({ agentId }) {
  if (agentId === 'codex') {
    return <img src={openAiIconUrl} alt="" aria-hidden="true" data-agent="codex" />;
  }

  if (agentId === 'gemini') {
    return (
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true" data-agent="gemini">
        <path d="M8 1.25c.38 3.3 3.45 6.37 6.75 6.75C11.45 8.38 8.38 11.45 8 14.75 7.62 11.45 4.55 8.38 1.25 8 4.55 7.62 7.62 4.55 8 1.25Z" fill="#8AB4F8" />
      </svg>
    );
  }

  if (agentId === 'copilot') {
    return <img src={githubCopilotIconUrl} alt="" aria-hidden="true" data-agent="copilot" />;
  }

  if (agentId === 'sdd') {
    return <img src={openAiIconUrl} alt="" aria-hidden="true" data-agent="codex" />;
  }

  return <AiChatAgentIcon icon={agentId} title="" />;
}

