function getCommitFileIcon(fileName = '') {
  const normalized = fileName.toLowerCase();
  if (normalized.endsWith('.html')) return 'fileTypes/html';
  if (normalized.endsWith('.js') || normalized.endsWith('.jsx')) return 'fileTypes/javaScript';
  if (normalized.endsWith('.css')) return 'fileTypes/css';
  if (normalized.endsWith('.java')) return 'fileTypes/java';
  if (normalized.endsWith('.md')) return 'fileTypes/markdown';
  if (normalized.endsWith('.xml')) return 'fileTypes/xml';
  return 'fileTypes/text';
}

const COMMIT_CHANGE_FILES = COMMIT_CHAT_GROUPS.flatMap((group) => (
  group.files.map((file, index) => ({
    ...file,
    id: `${group.id}-${index}`,
    groupId: group.id,
    groupLabel: group.label,
    path: file.path,
    icon: getCommitFileIcon(file.label),
  }))
));

// Severity ordering for the Commit tool window: critical first, then warning, info.
const COMMIT_SEVERITY_ORDER = ['critical', 'warning', 'info'];
const COMMIT_SEVERITY_LABEL = { critical: 'Critical', warning: 'Warning', info: 'Info' };

function reviewSeverityPriority(severity = '') {
  const index = COMMIT_SEVERITY_ORDER.indexOf(String(severity || '').trim().toLowerCase());
  return index === -1 ? COMMIT_SEVERITY_ORDER.length : index;
}

function highestReviewSeverityFromTotals(totals = {}) {
  return COMMIT_SEVERITY_ORDER.find((severity) => (totals?.[severity] ?? 0) > 0) ?? 'info';
}

function sortReviewFilesBySeverity(files = []) {
  return (Array.isArray(files) ? files : [])
    .map((file, index) => ({ file, index }))
    .sort((left, right) => (
      reviewSeverityPriority(highestReviewSeverityFromTotals(getStableReviewFileSeverityTotals(left.file)))
      - reviewSeverityPriority(highestReviewSeverityFromTotals(getStableReviewFileSeverityTotals(right.file)))
      || left.index - right.index
    ))
    .map(({ file }) => file);
}

// Include handled comments when deriving navigation/group order. Live
// `severityTotals` intentionally excludes accepted/dismissed findings, which
// used to make a file (and its card) jump as soon as a quick fix was applied.
function getStableReviewFileSeverityTotals(file = null) {
  const totals = { critical: 0, warning: 0, info: 0 };
  Object.values(normalizeStoredDiffCommentsState(file?.comments)).flat().forEach((comment) => {
    const severity = String(comment?.severity || '').trim().toLowerCase();
    if (severity in totals) totals[severity] += 1;
  });
  return Object.values(totals).some((count) => count > 0)
    ? totals
    : (file?.severityCounts ?? file?.severityTotals ?? totals);
}

function commitFilesPluralized(n, noun) {
  return `${n} ${noun}${n === 1 ? '' : 's'}`;
}

// Changed lines in a file — orders the rows inside a group.
function commitFileChangedLines(file) {
  return (file?.added ?? 0) + (file?.removed ?? 0);
}

// Build the grouped file tree for the active filter mode.
function buildCommitGroups(files = COMMIT_CHANGE_FILES, mode = 'directory') {
  if (mode === 'chat') {
    return COMMIT_CHAT_GROUPS.map((group) => {
      const children = files.filter((file) => file.groupId === group.id);
      return {
        id: `chat-changes-${group.id}`,
        label: group.label,
        count: commitFilesPluralized(children.length, 'file'),
        isExpanded: true,
        children,
      };
    });
  }

  if (mode === 'category') {
    const names = [...new Set(files.map((f) => f.category || 'Other'))].sort((a, b) => a.localeCompare(b));
    return names.map((name) => {
      const bucket = files
        .filter((f) => (f.category || 'Other') === name)
        .sort((a, b) => commitFileChangedLines(b) - commitFileChangedLines(a));
      return {
        id: `commit-cat-${name}`,
        label: name,
        count: commitFilesPluralized(bucket.length, 'file'),
        isExpanded: true,
        children: bucket,
      };
    });
  }

  // 'directory' (default): tracked changes and genuinely untracked files stay
  // distinct. Added files are already tracked in the prepared commit scope.
  const changed = files.filter((f) => f.status !== 'untracked');
  const unversioned = files.filter((f) => f.status === 'untracked');
  const groups = [];
  if (changed.length > 0) {
    groups.push({
      id: 'changes',
      label: 'Changes',
      count: commitFilesPluralized(changed.length, 'file'),
      isExpanded: true,
      children: changed,
    });
  }
  if (unversioned.length > 0) {
    groups.push({
      id: 'unversioned',
      label: 'Unversioned Files',
      count: commitFilesPluralized(unversioned.length, 'file'),
      isExpanded: true,
      children: unversioned,
    });
  }
  return groups;
}

// Reused Chats-History per-file severity counter: a coloured severity icon +
// count for each non-empty bucket (see AiNotesSeverityIcon / .aiux550-ainotes-*).
function CommitSeverityCounters({ counts }) {
  const c = counts ?? {};
  const total = (c.critical ?? 0) + (c.warning ?? 0) + (c.info ?? 0);
  if (total === 0) return null;
  return (
    <span
      className="aiux550-ainotes-file-severity"
      aria-label={`${c.critical ?? 0} critical, ${c.warning ?? 0} warning, ${c.info ?? 0} info`}
    >
      {COMMIT_SEVERITY_ORDER.map((sev) => (
        (c[sev] ?? 0) > 0 ? (
          <span className="aiux550-ainotes-sev-item" key={sev}>
            <AiNotesSeverityIcon severity={sev} />{c[sev]}
          </span>
        ) : null
      ))}
    </span>
  );
}

// Changed-line counters on a Commit row: "+27 -9", same add/remove colours the
// chat change cards use.
function CommitChangeCounters({ added = 0, removed = 0 }) {
  if (!added && !removed) return null;
  return (
    <span className="commit-file-change-summary" aria-label={`${added} added, ${removed} removed`}>
      <span className="ai-chat-diff-add">{`+${added}`}</span>
      {' '}
      <span className="ai-chat-diff-remove">{`-${removed}`}</span>
    </span>
  );
}

// Custom Commit tool window. Keeps the commit chrome, a grouped/collapsible file
// tree with checkboxes, and the bottom panel (amend + summary + Commit).
function CommitToolWindow({
  ctx,
  onOpenFile = null,
  onReviewContextChange = null,
  onStartReview = null,
}) {
  const [collapsedGroups, setCollapsedGroups] = useState(() => new Set());
  const [checkedIds, setCheckedIds] = useState(() => new Set(COMMIT_CHANGE_FILES.map((f) => f.id)));
  const [amend, setAmend] = useState(false);
  const [message, setMessage] = useState('');

  const groups = useMemo(() => buildCommitGroups(COMMIT_CHANGE_FILES, 'chat'), []);
  const reviewSourceAttachments = useMemo(() => (
    COMMIT_CHANGE_FILES
      .filter((file) => checkedIds.has(file.id))
      .map((file) => ({
        id: `commit-review-${file.id}`,
        label: file.label,
        icon: file.icon,
        path: `${file.path}/${file.label}`,
        sourcePath: `${file.path}/${file.label}`,
        sourceLabel: file.label,
        commitGroupLabel: file.groupLabel,
        commitStatus: file.status,
      }))
  ), [checkedIds]);
  useEffect(() => {
    onReviewContextChange?.({
      focused: ctx.focusedPanel === 'left',
      attachments: reviewSourceAttachments,
    });
    return () => onReviewContextChange?.(null);
  }, [ctx.focusedPanel, onReviewContextChange, reviewSourceAttachments]);
  const toggleGroup = (id) => setCollapsedGroups((prev) => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id); else next.add(id);
    return next;
  });
  const toggleFile = (id) => setCheckedIds((prev) => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id); else next.add(id);
    return next;
  });

  // Footer summary from the checked files' statuses.
  const summary = useMemo(() => {
    const tally = { modified: 0, added: 0, deleted: 0, renamed: 0, untracked: 0 };
    COMMIT_CHANGE_FILES.forEach((f) => {
      if (checkedIds.has(f.id) && tally[f.status] !== undefined) tally[f.status] += 1;
    });
    return ['modified', 'added', 'deleted', 'renamed', 'untracked']
      .filter((k) => tally[k] > 0)
      .map((k) => `${tally[k]} ${k}`)
      .join(', ');
  }, [checkedIds]);

  return (
    <ToolWindow
      title="Commit"
      width="100%"
      height="100%"
      actions={['more', 'minimize']}
      focused={ctx.focusedPanel === 'left'}
      onFocus={() => ctx.setFocusedPanel('left')}
      onActionClick={(action) => { if (action === 'minimize') ctx.setShowLeftPanel(false); }}
      className="commit-tool-window main-window-tool-window main-window-tool-window-left"
    >
      <div className="commit-custom">
        <div className="commit-toolbar">
          <IconButton icon="general/refresh" tooltip="Refresh" />
          <IconButton icon="vcs/revert" tooltip="Rollback" />
          <IconButton icon="vcs/patch" tooltip="Create Patch" />
          <IconButton icon="general/show" tooltip="Show" />
          <IconButton icon="general/expandAll" tooltip="Expand All" onClick={() => setCollapsedGroups(new Set())} />
          <IconButton icon="general/collapseAll" tooltip="Collapse All" onClick={() => setCollapsedGroups(new Set(groups.map((g) => g.id)))} />
        </div>

        <div className="commit-tree">
          {groups.map((group) => {
            const collapsed = collapsedGroups.has(group.id);
            const groupChecked = group.children.every((f) => checkedIds.has(f.id));
            const toggleGroupChecked = () => setCheckedIds((prev) => {
              const next = new Set(prev);
              const allOn = group.children.every((f) => next.has(f.id));
              group.children.forEach((f) => { if (allOn) next.delete(f.id); else next.add(f.id); });
              return next;
            });
            return (
              <div className="tree-node-container commit-custom-group" key={group.id}>
                {/* Group row = library TreeNode level 1 (paddingLeft 16). */}
                <div className="tree-node text-ui-default commit-group-node" style={{ paddingLeft: '16px' }}>
                  <button
                    type="button"
                    className="tree-node-toggle"
                    aria-expanded={!collapsed}
                    aria-label={collapsed ? 'Expand' : 'Collapse'}
                    onClick={() => toggleGroup(group.id)}
                  >
                    <Icon name={collapsed ? 'general/chevronRight' : 'general/chevronDown'} size={16} />
                  </button>
                  <Checkbox checked={groupChecked} onChange={toggleGroupChecked} />
                  <span className="commit-group-label">{group.label}</span>
                  <span className="commit-group-count">{group.count}</span>
                </div>
                {!collapsed && group.children.map((file) => (
                  /* File row = library TreeNode level 2 (paddingLeft 32, no toggle). */
                  <div className="tree-node text-ui-default commit-file-node" style={{ paddingLeft: '32px' }} key={file.id}>
                    {/* Spacer where the group's chevron sits, so the file's checkbox
                        aligns under the group's checkbox (proper nesting). */}
                    <span className="tree-node-spacer" />
                    <Checkbox
                      checked={checkedIds.has(file.id)}
                      onChange={() => toggleFile(file.id)}
                    />
                    <button
                      type="button"
                      className="commit-file-open"
                      onClick={() => onOpenFile?.(file)}
                      title={`Open ${file.label}`}
                    >
                      <Icon name={file.icon} size={16} className="commit-file-row-icon" />
                      <span className={`commit-file-name commit-status-${file.status}`}>{file.label}</span>
                      <span
                        className={`commit-file-vcs-status is-${file.status}`}
                        aria-label={`VCS status: ${file.status}`}
                        title={file.previousLabel
                          ? `${file.previousLabel} → ${file.label} · ${file.status}`
                          : file.status}
                      >
                        {{ modified: 'M', added: 'A', deleted: 'D', renamed: 'R', untracked: 'U' }[file.status] ?? 'M'}
                      </span>
                      <span className="commit-file-path">{file.path}</span>
                    </button>
                  </div>
                ))}
              </div>
            );
          })}
        </div>

        <div className="commit-bottom-panel">
          <div className="commit-amend-toolbar">
            <div className="commit-amend-left">
              <label className="commit-amend-label">
                <Checkbox checked={amend} onChange={() => setAmend((v) => !v)} />
                <span>Amend</span>
              </label>
              <IconButton icon="general/history" tooltip="Show History" />
              <IconButton icon="aiAssistant/aiAssistantColored" tooltip="Generate Commit Message" />
            </div>
            <span className="commit-modified-count">{summary}</span>
          </div>
          <div className="commit-message-area">
            <textarea
              className="commit-message-textarea"
              placeholder="Commit message"
              value={message}
              onChange={(event) => setMessage(event.target.value)}
            />
          </div>
          <div className="commit-actions">
            <div className="commit-buttons">
              <Button type="primary" disabled={checkedIds.size === 0}>Commit</Button>
              <Button type="secondary" disabled={checkedIds.size === 0}>Commit and Push...</Button>
            </div>
            <IconButton icon="general/settings" tooltip="Commit Options" />
          </div>
        </div>
      </div>
    </ToolWindow>
  );
}

