function AiChatTabView({
  chatId,
  scenarios = {},
  sentMessages = [],
  composerDraft = null,
  onComposerDraftChange = null,
  onSendMessage = null,
  onAgentChange = null,
  onOpenDiffTab = null,
  onOpenAttachment = null,
  composerDiffAttachments = [],
  onRemoveComposerAttachment = null,
  fallbackTitle = 'AI Chat',
  onAddContextPopupOpen = null,
  showNewContextOptionsIndicator = false,
  plainFileGutterCommentsEnabled = false,
  onPlainFileGutterCommentsEnabledChange = null,
  diffGutterCommentsEnabled = true,
  onDiffGutterCommentsEnabledChange = null,
  fileCommentsOptionIsNew = false,
  diffCommentsOptionIsNew = false,
  onFileCommentsOptionSeen = null,
  onDiffCommentsOptionSeen = null,
  agentRun = null,
  onStopMessage = null,
  onOpenReviewDiff = null,
  onCompleteReview = null,
  onCancelReview = null,
  onReviseReview = null,
  reviewFeedbackRequestKey = 0,
  onReviewFeedbackRequestHandled = null,
  reviewFiles = [],
  onReviewFileCommentsChange = null,
  onApplyReviewFile = null,
  onDismissReviewFile = null,
  chatAnnotations = [],
  scrollTarget = null,
  onEditAnnotation = null,
  onCreateSpec = null,
  onRunCodeReview = null,
  onCommitChanges = null,
  onOpenChangedFile = null,
  onOpenAgentTaskTab = null,
}) {
  const [addContextPopupRect, setAddContextPopupRect] = useState(null);
  const isAgentRunProcessing = ['queued', 'processing', 'updating'].includes(agentRun?.status);
  const scenario = scenarios?.[chatId] ?? {
    title: fallbackTitle,
    userPrompt: fallbackTitle,
    assistantParagraphs: [
      'I opened this existing chat in the editor tab with the current project context.',
    ],
    result: [
      'The conversation is ready to continue from this point.',
    ],
    command: 'Prepared project context',
  };
  const messageId = scenario?.messageId ?? `editor-chat-${chatId}`;
  const initialComposerText = typeof scenario?.initialComposerText === 'string' ? scenario.initialComposerText : '';
  const persistedComposerText = typeof composerDraft?.text === 'string'
    ? composerDraft.text
    : initialComposerText;
  const persistedComposerContentParts = Array.isArray(composerDraft?.contentParts)
    ? composerDraft.contentParts
    : [];
  const persistedDismissedAttachmentKeys = Array.isArray(composerDraft?.dismissedAttachmentKeys)
    ? composerDraft.dismissedAttachmentKeys.filter((key) => typeof key === 'string' && key.length > 0)
    : [];
  const initialSessionModel = typeof scenario?.initialModel === 'string' ? scenario.initialModel : null;
  const initialSessionEffort = typeof scenario?.initialEffort === 'string'
    ? scenario.initialEffort
    : (CODEX_STYLE_AGENT_IDS.includes(scenario?.icon) ? 'Extra High' : 'Medium effort');
  const initialSessionAccess = typeof scenario?.initialAccess === 'string' ? scenario.initialAccess : 'Full access';
  const [composerText, setComposerText] = useState(persistedComposerText);
  const [composerContentParts, setComposerContentParts] = useState(persistedComposerContentParts);
  // Attachments (diff/comment/spec chips) the user has already sent from this
  // composer. Keyed by content, not just id, so a chip that gets new comments
  // after being dismissed resurfaces instead of staying hidden forever.
  const [dismissedComposerAttachmentKeys, setDismissedComposerAttachmentKeys] = useState(
    () => new Set(persistedDismissedAttachmentKeys),
  );
  const scenarioAgentId = AI_CHAT_AGENTS.some((agent) => agent.id === scenario?.icon)
    ? scenario.icon
    : 'claude';
  const [selectedAgentId, setSelectedAgentId] = useState(scenarioAgentId);
  const [selectedModelOverride, setSelectedModelOverride] = useState(initialSessionModel);
  const [isAgentMenuOpen, setIsAgentMenuOpen] = useState(false);
  const [newSessionSettingsMenu, setNewSessionSettingsMenu] = useState(null);
  const [slashCommandIndex, setSlashCommandIndex] = useState(0);
  const [slashCommandMenuDismissed, setSlashCommandMenuDismissed] = useState(false);
  const [selectedEffort, setSelectedEffort] = useState(initialSessionEffort);
  const [selectedAccess, setSelectedAccess] = useState(initialSessionAccess);
  const [selectedEditMode, setSelectedEditMode] = useState('Accepts Edits');
  const [isNewSessionComposerExpanded, setIsNewSessionComposerExpanded] = useState(false);
  // SDD mode: On by default (AIUX-639) — a Codex-style-agent-only toggle shown at the
  // bottom-right of the composer footer, next to the model/effort/mode pills.
  const [sddModeOn, setSddModeOn] = useState(true);
  const composerRef = useRef(null);
  const composerDraftRef = useRef(composerDraft);
  composerDraftRef.current = composerDraft;
  const previousComposerAttachmentStateRef = useRef({ chatId: null, ids: [] });
  const composerContentPartIdRef = useRef(persistedComposerContentParts.reduce((highestId, part) => {
    const match = typeof part?.id === 'string' ? part.id.match(/-(\d+)$/u) : null;
    return match ? Math.max(highestId, Number.parseInt(match[1], 10)) : highestId;
  }, 0));
  const scrollRef = useRef(null);
  const agentPickerRef = useRef(null);
  const newSessionSettingsRef = useRef(null);
  const [composerAttachmentsExpanded, setComposerAttachmentsExpanded] = useState(false);
  const [composerAttachmentContextMenu, setComposerAttachmentContextMenu] = useState(null);
  const [resolvedReviewDecisionId, setResolvedReviewDecisionId] = useState(null);
  const [reviewFeedbackMessageId, setReviewFeedbackMessageId] = useState(null);
  const handledReviewFeedbackRequestRef = useRef(0);
  const [queuedFollowUps, setQueuedFollowUps] = useState([]);
  const [processedReviewScopeFileCount, setProcessedReviewScopeFileCount] = useState(0);
  const queuedFollowUpIdRef = useRef(0);
  useEffect(() => {
    setSelectedAgentId(scenarioAgentId);
  }, [chatId, scenarioAgentId]);
  const conversationTurns = Array.isArray(scenario?.conversationTurns)
    ? scenario.conversationTurns
    : [];
  const sentMessageScrollKey = sentMessages
    .map((message) => [
      message.id,
      message.kind ?? '',
      message.streaming ? 'streaming' : 'done',
      message.reviewSummary?.commentCount ?? '',
    ].join(':'))
    .join('|');
  const isSpecChat = Boolean(scenario?.isSpecChat || String(chatId).startsWith('spec-chat-'));
  const isNewSessionState = Boolean(scenario?.emptyState)
    && !scenario?.temporary
    && sentMessages.length === 0
    && conversationTurns.length === 0;
  const readyReviewMessage = [...sentMessages].reverse().find((message) => (
    message?.role === 'assistant' && message?.kind === 'review-summary'
  )) ?? null;
  const isReviewFinal = agentRun?.kind === 'review'
    && (agentRun?.status === 'completed' || agentRun?.status === 'cancelled');
  const isReviewFeedbackMode = Boolean(
    !isReviewFinal && readyReviewMessage && readyReviewMessage.id === reviewFeedbackMessageId,
  );
  const isReviewDecisionReady = Boolean(
    !isReviewFinal && readyReviewMessage && readyReviewMessage.id !== resolvedReviewDecisionId,
  );
  useEffect(() => {
    if (!isAgentRunProcessing) setQueuedFollowUps([]);
  }, [isAgentRunProcessing]);
  const reviewScopeQueueFiles = Array.isArray(agentRun?.files) ? agentRun.files : [];
  const reviewScopeQueueSignature = reviewScopeQueueFiles
    .map((file) => `${file.id}:${file.sourceLabel}`)
    .join('|');
  useEffect(() => {
    setProcessedReviewScopeFileCount(0);
    if (!isAgentRunProcessing || reviewScopeQueueFiles.length === 0) return undefined;

    const stepDuration = Math.max(700, Math.floor(3600 / reviewScopeQueueFiles.length));
    const intervalId = window.setInterval(() => {
      setProcessedReviewScopeFileCount((count) => Math.min(reviewScopeQueueFiles.length, count + 1));
    }, stepDuration);

    return () => window.clearInterval(intervalId);
  }, [agentRun?.iteration, chatId, isAgentRunProcessing, reviewScopeQueueSignature]);
  const reviewScopeQueueItems = reviewScopeQueueFiles.map((file, index) => ({
    id: file.id,
    text: file.sourceLabel,
    icon: agentRunFileIconName(file.sourceLabel),
    status: index < processedReviewScopeFileCount
      ? 'done'
      : (index === processedReviewScopeFileCount ? 'processing' : 'queued'),
  }));
  const showCodeReviewPrompt = chatId === DEFAULT_OPEN_CHAT_ID
    && agentRun?.kind !== 'review'
    && !readyReviewMessage
    && Boolean(onRunCodeReview);
  const reviewPromptFiles = getChatChangeCards(scenario);
  const selectedAgent = AI_CHAT_AGENTS.find((agent) => agent.id === selectedAgentId) ?? AI_CHAT_AGENTS[0];
  const isCodexStyleAgent = CODEX_STYLE_AGENT_IDS.includes(selectedAgentId);
  const composerEffortOptions = isCodexStyleAgent
    ? ['Low', 'Medium', 'High', 'Extra High']
    : ['Low effort', 'Medium effort', 'High effort'];
  const selectedModelLabel = selectedModelOverride ?? selectedAgent.model;
  const newSessionModelOptions = [
    selectedModelLabel,
    selectedAgent.model,
    'Default model',
  ].filter((label, index, labels) => labels.indexOf(label) === index);
  const chatModelOptions = [
    selectedModelLabel,
    'Sonnet 1M',
    '5.6 Sol',
    'GPT-5.2-Codex',
  ].filter((label, index, labels) => labels.indexOf(label) === index);
  const scenarioAttachments = Array.isArray(scenario?.attachments) ? scenario.attachments : [];
  // Keep quote highlights after Send by reading context from both the live
  // composer and the attachments already stored on user messages.
  const visibleChatAnnotations = useMemo(() => {
    const sentContextAnnotations = sentMessages.flatMap((message) => (
      (Array.isArray(message?.attachments) ? message.attachments : []).flatMap((attachment) => [
        ...(attachment?.isChatAnnotation && Array.isArray(attachment.annotations) ? attachment.annotations : []),
        ...getChatSelectionContextHighlights([attachment]),
      ])
    ));
    return [...(Array.isArray(chatAnnotations) ? chatAnnotations : []), ...sentContextAnnotations]
      .filter((annotation, index, annotations) => (
        annotations.findIndex((candidate) => candidate?.id === annotation?.id) === index
      ));
  }, [chatAnnotations, sentMessages]);
  const renderAnnotatedParagraph = useCallback((text, blockId, paragraphMessageId = messageId) => (
    renderAiChatAnnotatedText(
      text,
      getAiChatBlockAnnotations(visibleChatAnnotations, paragraphMessageId, blockId),
      onEditAnnotation,
    )
  ), [messageId, onEditAnnotation, visibleChatAnnotations]);
  const focusComposerAtEnd = useCallback(() => {
    const focus = () => {
      const textarea = composerRef.current;
      if (!textarea) return;
      textarea.focus({ preventScroll: true });
      const caretPosition = textarea.value.length;
      textarea.setSelectionRange(caretPosition, caretPosition);
    };
    requestAnimationFrame(() => requestAnimationFrame(focus));
  }, []);

  useEffect(() => {
    const savedDraft = composerDraftRef.current;
    setComposerText(typeof savedDraft?.text === 'string' ? savedDraft.text : initialComposerText);
    setComposerContentParts(Array.isArray(savedDraft?.contentParts) ? savedDraft.contentParts : []);
    setDismissedComposerAttachmentKeys(new Set(
      Array.isArray(savedDraft?.dismissedAttachmentKeys) ? savedDraft.dismissedAttachmentKeys : [],
    ));
    setSelectedAgentId(scenarioAgentId);
    setSelectedModelOverride(initialSessionModel);
    setIsAgentMenuOpen(false);
    setNewSessionSettingsMenu(null);
    setSelectedEffort(initialSessionEffort);
    setSelectedAccess(initialSessionAccess);
    setIsNewSessionComposerExpanded(false);
    focusComposerAtEnd();
  }, [chatId, focusComposerAtEnd, initialComposerText, initialSessionAccess, initialSessionEffort, initialSessionModel, scenarioAgentId]);

  useEffect(() => {
    onComposerDraftChange?.(chatId, {
      text: composerText,
      contentParts: composerContentParts,
      dismissedAttachmentKeys: [...dismissedComposerAttachmentKeys],
    });
  }, [chatId, composerContentParts, composerText, dismissedComposerAttachmentKeys, onComposerDraftChange]);

  useEffect(() => {
    setResolvedReviewDecisionId(null);
    setReviewFeedbackMessageId(null);
  }, [chatId]);

  useEffect(() => {
    if (!isAgentMenuOpen) return undefined;

    const handlePointerDown = (event) => {
      const target = event.target;
      if (target instanceof Node && agentPickerRef.current?.contains(target)) return;
      setIsAgentMenuOpen(false);
    };
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') setIsAgentMenuOpen(false);
    };

    document.addEventListener('mousedown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('mousedown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isAgentMenuOpen]);

  useEffect(() => {
    if (!newSessionSettingsMenu) return undefined;

    const handlePointerDown = (event) => {
      const target = event.target;
      if (target instanceof Node && newSessionSettingsRef.current?.contains(target)) return;
      // The picker's own dropdown is a FinalAnchoredPopup now — portaled to
      // document.body, so it's never a DOM descendant of the footer above.
      // Without this check, this "outside click" listener (mousedown) fires
      // and clears newSessionSettingsMenu before the later click event ever
      // reaches the option button, so nothing you click in the popup does
      // anything.
      if (target instanceof Element && target.closest('[data-final-popup]')) return;
      setNewSessionSettingsMenu(null);
    };
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') setNewSessionSettingsMenu(null);
    };

    document.addEventListener('mousedown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('mousedown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [newSessionSettingsMenu]);

  useEffect(() => {
    const scrollElement = scrollRef.current;
    if (!scrollElement) return;
    // Opening a chat shows it from the top (prompt → answer → changes → result);
    // only jump to the latest once the user has sent a message.
    const targetScrollTop = sentMessages.length > 0 ? scrollElement.scrollHeight : 0;
    scrollElement.scrollTop = targetScrollTop;
    if (sentMessages.length > 0) {
      requestAnimationFrame(() => {
        if (scrollRef.current) {
          scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
      });
    }
  }, [chatId, sentMessages.length, sentMessageScrollKey]);

  useEffect(() => {
    const targetMessageId = scrollTarget?.chatId === chatId ? scrollTarget.messageId : null;
    const targetAnnotationId = scrollTarget?.chatId === chatId ? scrollTarget.annotationId : null;
    if (!targetMessageId && !targetAnnotationId) return undefined;

    let frameId = 0;
    let timeoutId = 0;
    let highlightTimeoutId = 0;
    let highlightedElement = null;
    const scrollToTarget = (attempt = 0) => {
      const scrollElement = scrollRef.current;
      if (!scrollElement) return;

      const highlightedQuote = targetAnnotationId
        ? Array.from(scrollElement.querySelectorAll('[data-ai-chat-annotation-id]')).find(
            (node) => node instanceof HTMLElement && node.dataset.aiChatAnnotationId === targetAnnotationId,
          )
        : null;
      const targetElement = highlightedQuote ?? Array.from(scrollElement.querySelectorAll('.aiux543-user-message[data-ai-chat-message-id], [data-ai-chat-annotatable="true"][data-ai-chat-message-id]')).find(
          (node) => node instanceof HTMLElement && node.dataset.aiChatMessageId === targetMessageId,
        );

      if (targetElement instanceof HTMLElement) {
        targetElement.scrollIntoView({ block: 'center', behavior: 'smooth' });
        if (highlightedQuote instanceof HTMLElement) {
          highlightedElement = highlightedQuote;
          highlightedElement.classList.remove('is-navigation-highlight');
          // Restart the emphasis when the same quote chip is clicked repeatedly.
          void highlightedElement.offsetWidth;
          highlightedElement.classList.add('is-navigation-highlight');
          highlightTimeoutId = window.setTimeout(() => {
            highlightedElement?.classList.remove('is-navigation-highlight');
          }, 900);
        }
        return;
      }

      if (attempt < 10) {
        timeoutId = window.setTimeout(() => scrollToTarget(attempt + 1), 50);
      }
    };

    frameId = window.requestAnimationFrame(() => scrollToTarget());

    return () => {
      if (frameId) window.cancelAnimationFrame(frameId);
      if (timeoutId) window.clearTimeout(timeoutId);
      if (highlightTimeoutId) window.clearTimeout(highlightTimeoutId);
      highlightedElement?.classList.remove('is-navigation-highlight');
    };
  }, [chatId, scrollTarget?.annotationId, scrollTarget?.chatId, scrollTarget?.messageId, scrollTarget?.nonce]);

  const rawEditorComposerAttachments = Array.isArray(composerDiffAttachments) ? composerDiffAttachments : [];
  const getEditorComposerAttachmentDraftKey = (attachment, index = 0) => {
    const attachmentId = getAiChatAttachmentSequenceKey(attachment, index);
    const previewFingerprint = getAiChatAttachmentCommentPreviewItems(attachment).map((item) => ({
      text: item?.text ?? '',
      sourceLabel: item?.sourceLabel ?? '',
      lineLabel: item?.lineLabel ?? '',
      isSelectionContextPreview: Boolean(item?.isSelectionContextPreview),
    }));
    return `${attachmentId}␀${JSON.stringify(previewFingerprint)}`;
  };
  const rawEditorComposerAttachmentDraftKeys = rawEditorComposerAttachments.map(getEditorComposerAttachmentDraftKey);
  const rawEditorComposerAttachmentDraftSignature = rawEditorComposerAttachmentDraftKeys.join('\n');
  useEffect(() => {
    // Once a dismissed attachment's underlying content changes (e.g. a new
    // comment gets added to a note that was already sent), it should resurface
    // instead of staying hidden under its now-stale dismissal key forever.
    const liveKeys = new Set(rawEditorComposerAttachmentDraftKeys);
    setDismissedComposerAttachmentKeys((current) => {
      const next = new Set([...current].filter((key) => liveKeys.has(key)));
      return next.size === current.size ? current : next;
    });
  }, [chatId, rawEditorComposerAttachmentDraftSignature]);
  const editorComposerAttachments = rawEditorComposerAttachments.filter((attachment, index) => (
    !dismissedComposerAttachmentKeys.has(getEditorComposerAttachmentDraftKey(attachment, index))
  ));
  const hasComposerCommentAttachment = editorComposerAttachments
    .some((attachment) => Number.isFinite(attachment?.commentCount) && attachment.commentCount > 0);
  const hasSelectionContextAttachment = editorComposerAttachments
    .some((attachment) => attachment?.isSelectionContext);
  const editorComposerAttachmentIds = editorComposerAttachments.map(getAiChatAttachmentSequenceKey);
  const editorComposerAttachmentSignature = editorComposerAttachmentIds.join('\n');
  const hasComposerAttachmentOverflow = editorComposerAttachments.length > COMPOSER_ATTACHMENT_COLLAPSED_LIMIT;
  const committedComposerText = composerContentParts
    .filter((part) => part.type === 'text')
    .map((part) => part.text)
    .join(' ')
    .trim();
  const hasReviewFindings = Number(readyReviewMessage?.reviewSummary?.commentCount ?? 0) > 0
    || (Array.isArray(reviewFiles) && reviewFiles.some((file) => (
      Object.values(normalizeStoredDiffCommentsState(file?.comments)).flat().length > 0
    )));
  const hasReviewFeedbackBatch = (Array.isArray(reviewFiles) ? reviewFiles : []).some((file) => (
    Object.values(normalizeStoredDiffCommentsState(file?.comments)).flat().some((comment) => {
      const status = getReviewFindingStatus(comment);
      return status !== 'open'
        || Boolean(comment?.isReviewFeedback)
        || comment?.author === 'user'
        || (typeof comment?.userReply === 'string' && comment.userReply.trim().length > 0);
    })
  )) || (Array.isArray(composerDiffAttachments) ? composerDiffAttachments : []).some((attachment) => (
    Number.isFinite(attachment?.commentCount) && attachment.commentCount > 0
  ));
  const reviewFeedbackMessage = Array.from(new Set(
    (Array.isArray(reviewFiles) ? reviewFiles : []).flatMap((file) => (
      Object.values(normalizeStoredDiffCommentsState(file?.comments)).flatMap((comment) => {
        const userReply = typeof comment?.userReply === 'string' ? comment.userReply.trim() : '';
        if (userReply) return [userReply];
        if (comment?.author === 'user' || comment?.isReviewFeedback) {
          const commentText = getStoredCommentText(comment).trim();
          return commentText ? [commentText] : [];
        }
        return [];
      })
    )),
  )).join('\n') || 'Submitted review feedback.';
  const canSend = composerText.trim().length > 0
    || committedComposerText.length > 0
    || hasComposerCommentAttachment
    || hasSelectionContextAttachment
    // A review with findings can be submitted after decisions/replies even
    // without an extra message: those decisions are the feedback batch.
    || (isReviewFeedbackMode && hasReviewFindings);
  const slashCommandMatch = composerText.match(/^\/([^\s]*)$/);
  const slashCommandQuery = slashCommandMatch?.[1]?.toLowerCase() ?? null;
  const filteredSlashCommands = slashCommandQuery == null
    ? []
    : AI_CHAT_SLASH_COMMANDS.filter(({ command }) => command.slice(1).includes(slashCommandQuery));
  const showSlashCommandMenu = !isAgentRunProcessing
    && !slashCommandMenuDismissed
    && filteredSlashCommands.length > 0;
  const activeSlashCommandIndex = Math.min(slashCommandIndex, Math.max(0, filteredSlashCommands.length - 1));
  const insertSlashCommand = useCallback((command) => {
    setComposerText(`${command} `);
    setSlashCommandMenuDismissed(true);
    focusComposerAtEnd();
  }, [focusComposerAtEnd]);

  useEffect(() => {
    const previous = previousComposerAttachmentStateRef.current;
    const chatChanged = previous.chatId !== chatId;
    const previousIds = new Set(chatChanged ? [] : previous.ids);
    const addedIds = editorComposerAttachmentIds.filter((id) => !previousIds.has(id));
    const representedComposerAttachmentIds = new Set(
      composerContentParts
        .filter((part) => part.type === 'attachment')
        .map((part) => part.attachmentId),
    );
    const attachmentIdsToInsert = addedIds.filter((id) => !representedComposerAttachmentIds.has(id));

    setComposerContentParts((prev) => {
      const liveAttachmentIds = new Set(editorComposerAttachmentIds);
      const retainedParts = prev.filter((part) => (
        part.type !== 'attachment' || liveAttachmentIds.has(part.attachmentId)
      ));
      const next = [...retainedParts];
      const representedAttachmentIds = new Set(
        retainedParts
          .filter((part) => part.type === 'attachment')
          .map((part) => part.attachmentId),
      );
      const unrepresentedAttachmentIds = attachmentIdsToInsert.filter((id) => !representedAttachmentIds.has(id));
      if (unrepresentedAttachmentIds.length > 0 && composerText.length > 0) {
        composerContentPartIdRef.current += 1;
        next.push({
          id: `text-${composerContentPartIdRef.current}`,
          type: 'text',
          text: composerText,
        });
      }
      unrepresentedAttachmentIds.forEach((attachmentId) => {
        composerContentPartIdRef.current += 1;
        next.push({
          id: `attachment-${composerContentPartIdRef.current}`,
          type: 'attachment',
          attachmentId,
        });
      });
      return next;
    });

    if (attachmentIdsToInsert.length > 0) {
      if (composerText.length > 0) setComposerText('');
      focusComposerAtEnd();
    }

    previousComposerAttachmentStateRef.current = { chatId, ids: editorComposerAttachmentIds };
  }, [chatId, editorComposerAttachmentSignature, focusComposerAtEnd]);
  const composerAttachmentById = new Map(editorComposerAttachments.map((attachment, index) => [
    getAiChatAttachmentSequenceKey(attachment, index),
    attachment,
  ]));
  const editorComposerAttachmentDraftKeys = editorComposerAttachments.map(getEditorComposerAttachmentDraftKey);
  const dismissSentComposerAttachments = () => {
    if (editorComposerAttachmentDraftKeys.length === 0) return;
    setDismissedComposerAttachmentKeys((current) => new Set([
      ...current,
      ...editorComposerAttachmentDraftKeys,
    ]));
  };
  const sendReviewFeedback = (messageText = '', contentParts = []) => {
    if (!readyReviewMessage || isReviewFinal) return;
    const submittedMessageText = String(messageText || '').trim() || reviewFeedbackMessage;
    setResolvedReviewDecisionId(readyReviewMessage.id);
    setReviewFeedbackMessageId(null);
    if (onReviseReview) {
      onReviseReview(chatId, submittedMessageText, editorComposerAttachments);
    } else {
      onSendMessage?.(chatId, submittedMessageText, editorComposerAttachments, {
        contentParts,
        forceReview: true,
      });
    }
    dismissSentComposerAttachments();
    setComposerText('');
    setComposerContentParts([]);
  };
  const handleSend = () => {
    if (!canSend) return;
    const contentParts = [
      ...composerContentParts,
      ...(composerText.trim().length > 0
        ? [{ id: 'live-text', type: 'text', text: composerText }]
        : []),
    ];
    const messageText = contentParts
      .filter((part) => part.type === 'text')
      .map((part) => part.text)
      .join(' ')
      .trim();
    if (isAgentRunProcessing) {
      if (!messageText) return;
      queuedFollowUpIdRef.current += 1;
      setQueuedFollowUps((items) => [{
        id: `review-follow-up-${queuedFollowUpIdRef.current}`,
        text: messageText,
      }, ...items]);
      setComposerText('');
      setComposerContentParts([]);
      focusComposerAtEnd();
      return;
    }
    if (isReviewFeedbackMode) {
      sendReviewFeedback(messageText, contentParts);
      return;
    }
    const startsReview = /(^\/review\b)|(^review\b)|(\breview this\b)/i.test(messageText);
    onSendMessage?.(chatId, messageText, editorComposerAttachments, {
      contentParts: contentParts.map((part) => (part.type === 'attachment'
        ? { type: 'attachment', attachmentId: part.attachmentId }
        : { type: 'text', text: part.text })),
      forceReview: startsReview,
      reviewConfiguration: startsReview ? {
        agentId: selectedAgentId,
        agentIcon: selectedAgentId,
        sessionId: chatId,
        dedicatedSession: false,
        modelLabel: selectedModelLabel,
        effortLabel: selectedEffort,
        scopeId: editorComposerAttachments.length > 0 ? 'current' : 'all',
        launchSource: 'current-chat',
        instructions: messageText.replace(/^\/review\b/iu, '').trim(),
      } : null,
    });
    dismissSentComposerAttachments();
    setComposerText('');
    setComposerContentParts([]);
  };

  useEffect(() => {
    if (!reviewFeedbackRequestKey) {
      handledReviewFeedbackRequestRef.current = 0;
      return;
    }
    if (
      reviewFeedbackRequestKey === handledReviewFeedbackRequestRef.current
      || !readyReviewMessage
      || isReviewFinal
    ) return;
    handledReviewFeedbackRequestRef.current = reviewFeedbackRequestKey;
    onReviewFeedbackRequestHandled?.(chatId, reviewFeedbackRequestKey);
    if (hasReviewFeedbackBatch) {
      sendReviewFeedback(composerText.trim(), [
        ...composerContentParts,
        ...(composerText.trim().length > 0
          ? [{ id: 'live-text', type: 'text', text: composerText }]
          : []),
      ]);
      return;
    }
    setReviewFeedbackMessageId(readyReviewMessage.id);
    setResolvedReviewDecisionId(readyReviewMessage.id);
    focusComposerAtEnd();
  }, [reviewFeedbackRequestKey]);

  useEffect(() => {
    if (hasComposerAttachmentOverflow) return;
    setComposerAttachmentsExpanded(false);
  }, [hasComposerAttachmentOverflow]);

  const handleComposerAttachmentContextMenu = useCallback((event, attachment) => {
    event.preventDefault();
    event.stopPropagation();
    setComposerAttachmentContextMenu({
      attachment,
      x: event.clientX,
      y: event.clientY,
    });
  }, []);

  const handleComposerAttachmentOpen = useCallback((attachment) => {
    if (onOpenAttachment) {
      onOpenAttachment(attachment, { messageId, chatId, archived: false });
      return;
    }
    if (onOpenDiffTab && attachment?.diffRequest) onOpenDiffTab(attachment.diffRequest);
  }, [chatId, messageId, onOpenAttachment, onOpenDiffTab]);

  const handleClearAllComposerAttachmentsFromMenu = useCallback(() => {
    editorComposerAttachments.forEach((attachment) => {
      onRemoveComposerAttachment?.(attachment, { chatId });
    });
    setComposerAttachmentsExpanded(false);
  }, [chatId, editorComposerAttachments, onRemoveComposerAttachment]);
  const renderComposerAttachment = (attachment, partId) => (
    <AiChatAttachmentStrip
      key={partId}
      attachments={attachment ? [attachment] : []}
      collapsedLimit={COMPOSER_ATTACHMENT_COLLAPSED_LIMIT}
      expanded={composerAttachmentsExpanded}
      onExpandedChange={setComposerAttachmentsExpanded}
      getCommentPreviewItems={getAiChatAttachmentCommentPreviewItems}
      onOpen={onOpenAttachment || onOpenDiffTab ? handleComposerAttachmentOpen : null}
      onContextMenu={handleComposerAttachmentContextMenu}
      onRemove={onRemoveComposerAttachment
        ? (attachment) => onRemoveComposerAttachment(attachment, { chatId })
        : null}
      className="aiux543-composer-attachments is-inline-composer-attachments"
      chipClassName="aiux543-composer-attachment-chip"
      removeButtonClassName="aiux543-composer-attachment-remove"
      removeLabel={(attachment) => `Remove ${attachment.label ?? 'attachment'}`}
      stopClickPropagation
    />
  );
  const representedComposerAttachmentIds = new Set(composerContentParts
    .filter((part) => part.type === 'attachment')
    .map((part) => part.attachmentId));
  const orderedComposerParts = [
    ...composerContentParts,
    ...editorComposerAttachmentIds
      .filter((attachmentId) => !representedComposerAttachmentIds.has(attachmentId))
      .map((attachmentId) => ({ id: `pending-${attachmentId}`, type: 'attachment', attachmentId })),
  ];
  const handleComposerBackspace = (event) => {
    if (
      event.key !== 'Backspace'
      || event.nativeEvent?.isComposing
      || event.currentTarget.selectionStart !== 0
      || event.currentTarget.selectionEnd !== 0
      || composerText.length > 0
    ) {
      return false;
    }

    const lastPart = orderedComposerParts[orderedComposerParts.length - 1];
    if (!lastPart) return false;

    if (lastPart.type === 'attachment') {
      const attachment = composerAttachmentById.get(lastPart.attachmentId);
      if (!attachment || !onRemoveComposerAttachment) return false;
      event.preventDefault();
      setComposerContentParts((parts) => parts.filter((part) => (
        part.type !== 'attachment' || part.attachmentId !== lastPart.attachmentId
      )));
      onRemoveComposerAttachment(attachment, { chatId });
      return true;
    }

    if (lastPart.type === 'text' && typeof lastPart.text === 'string') {
      event.preventDefault();
      setComposerContentParts((parts) => parts.filter((part) => part.id !== lastPart.id));
      setComposerText(lastPart.text.slice(0, -1));
      focusComposerAtEnd();
      return true;
    }

    return false;
  };

  return (
    <div className={`aiux543-conversation${isNewSessionState ? ' is-new-session' : ''}${isReviewDecisionReady ? ' is-review-decision-ready' : ''}`}>
      <div ref={scrollRef} className="aiux543-conversation-scroll">
        {conversationTurns.length > 0 ? (
          conversationTurns.map((turn, index) => (
            turn?.role === 'user' ? (
              <div key={`turn-${index}`} className="aiux543-user-message aiux543-thread-user-message" data-ai-chat-message-id={`${messageId}-turn-${index}`}>
                <p>{turn.text}</p>
              </div>
            ) : (
              <article key={`turn-${index}`} className="aiux543-answer aiux543-thread-answer">
                <h3>Claude Agent</h3>
                {(Array.isArray(turn?.paragraphs) ? turn.paragraphs : [turn?.text].filter(Boolean)).map((paragraph, paragraphIndex) => (
                  <p
                    key={`turn-${index}-paragraph-${paragraphIndex}`}
                    data-ai-chat-annotatable="true"
                    data-ai-chat-message-id={`${messageId}-turn-${index}`}
                    data-ai-chat-block-id={`turn-${index}-paragraph-${paragraphIndex}`}
                  >
                    {renderAnnotatedParagraph(paragraph, `turn-${index}-paragraph-${paragraphIndex}`, `${messageId}-turn-${index}`)}
                  </p>
                ))}
              </article>
            )
          ))
        ) : (
          <>
            {isSpecChat && scenario?.userPrompt ? (
              <ChatUserCard
                messageId={messageId}
                attachments={scenarioAttachments}
                onAttachmentOpen={(attachment) => {
                  if (onOpenAttachment) {
                    onOpenAttachment(attachment, { messageId, chatId, archived: true });
                    return;
                  }
                  if (attachment?.diffRequest) onOpenDiffTab?.(attachment.diffRequest);
                }}
              >
                {scenario.userPrompt}
              </ChatUserCard>
            ) : scenario?.userPrompt ? (
              <div className="aiux543-user-message" data-ai-chat-message-id={messageId}>
                <p>{scenario.userPrompt}</p>
              </div>
            ) : null}

            {!isSpecChat && scenarioAttachments.length > 0 && (
              <div className="aiux543-user-attachments">
                {scenarioAttachments.map((attachment) => {
                  const openAttachment = onOpenAttachment && (attachment.diffRequest || attachment.isPlainFile || attachment.isSddDocument)
                    ? () => onOpenAttachment(attachment, { messageId, chatId, archived: true })
                    : (attachment.diffRequest && onOpenDiffTab
                        ? () => onOpenDiffTab(attachment.diffRequest)
                        : (scenario.diffRequest && onOpenDiffTab ? () => onOpenDiffTab(scenario.diffRequest) : null));
                  const previewItems = getAiChatAttachmentCommentPreviewItems(attachment);

                  return (
                    <button
                      key={attachment.id ?? attachment.label}
                      type="button"
                      className="ai-chat-attachment-chip aiux543-user-attachment-chip"
                      onClick={openAttachment ?? undefined}
                    >
                      <AiChatAttachmentIcon icon={attachment.icon} />
                      <span className="ai-chat-attachment-name">{attachment.label}</span>
                      {getAiChatAttachmentInlineCount(attachment) > 0 && (
                        <span className="ai-chat-attachment-comment-count">
                          <span className="ai-chat-attachment-comment-count-separator" aria-hidden="true">&middot;</span>
                          <span className="ai-chat-attachment-comment-count-value">{getAiChatAttachmentInlineCount(attachment)}</span>
                        </span>
                      )}
                      {previewItems.length > 0 && (
                        <span className="ai-chat-attachment-comment-preview ai-chat-attachment-comment-preview-library" role="tooltip">
                          <AttachmentCommentHoverCard items={previewItems} contextLabel={attachment.label} />
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            )}

            {Array.isArray(scenario?.transcriptBlocks) && scenario.transcriptBlocks.map((block, idx) => (
              <AiChatTranscriptBlock key={`transcript-${idx}`} block={block} />
            ))}

            {scenario?.assistantParagraphs?.length > 0 && (
              <article className="aiux543-answer">
                <h3>{scenario.assistantHeading || 'What changed'}</h3>
                {scenario.assistantParagraphs.map((paragraph, idx) => (
                  <p
                    key={`assistant-${idx}`}
                    data-ai-chat-annotatable="true"
                    data-ai-chat-message-id={messageId}
                    data-ai-chat-block-id={`assistant-${idx}`}
                  >
                    {renderAnnotatedParagraph(paragraph, `assistant-${idx}`)}
                  </p>
                ))}
              </article>
            )}
          </>
        )}

        {!scenario.workedForLabel && (hasChatChangedFilesList(scenario) ? (
          // "N files changed" (edited-files style), not the plain "Done" card —
          // every chat reports its finished iterations the same way now.
          <ChatEditedFilesCard
            files={getChatChangeCards(scenario)}
            onOpenFile={onOpenDiffTab ? (file) => onOpenDiffTab(file.diffRequest) : null}
            onOpenReview={onOpenDiffTab ? () => {
              const firstDiffRequest = getChatChangeCards(scenario)
                .map((card) => card?.diffRequest)
                .find(Boolean);
              if (firstDiffRequest) onOpenDiffTab(firstDiffRequest);
            } : null}
          />
        ) : getChatChangeCards(scenario).map((card) => {
          const openDiff = card.diffRequest && onOpenDiffTab ? () => onOpenDiffTab(card.diffRequest) : null;

          return (
            <section
              key={card.id ?? card.name}
              className={`aiux543-code-card${openDiff ? ' aiux543-code-card-clickable' : ''}`}
              role={openDiff ? 'button' : undefined}
              tabIndex={openDiff ? 0 : undefined}
              onClick={openDiff ?? undefined}
              onKeyDown={openDiff ? (event) => {
                if (event.key !== 'Enter' && event.key !== ' ') return;
                event.preventDefault();
                openDiff();
              } : undefined}
            >
              <header>
                <Icon className="aiux543-file-icon" name={card.icon ?? 'fileTypes/java'} size={16} />
                <strong>{card.name}</strong>
                <span className="aiux543-diff-inline">{card.added}</span>
                <span className="aiux543-diff-inline aiux543-diff-inline-removed">{card.removed}</span>
                <em>Edited</em>
              </header>
              <SyntaxCode code={card.code} />
            </section>
          );
        }))}

        {Array.isArray(scenario?.result) && scenario.result.length > 0 && (
          scenario.workedForLabel ? (
            <ul className="aiux543-answer-result-list">
              {scenario.result.map((paragraph, idx) => (
                <li
                  key={`result-${idx}`}
                  data-ai-chat-annotatable="true"
                  data-ai-chat-message-id={messageId}
                  data-ai-chat-block-id={`result-${idx}`}
                >
                  {renderAnnotatedParagraph(paragraph, `result-${idx}`)}
                </li>
              ))}
            </ul>
          ) : (
            <article className="aiux543-answer">
              <h3>Result</h3>
              {scenario.result.map((paragraph, idx) => (
                <p
                  key={`result-${idx}`}
                  data-ai-chat-annotatable="true"
                  data-ai-chat-message-id={messageId}
                  data-ai-chat-block-id={`result-${idx}`}
                >
                  {renderAnnotatedParagraph(paragraph, `result-${idx}`)}
                </p>
              ))}
            </article>
          )
        )}

        {scenario?.command && (
          scenario.workedForLabel ? (
            <p className="aiux543-answer-command-plain">{scenario.command}</p>
          ) : (
            <section className="aiux543-detail-trail">
              <article className="aiux543-detail-card">
                <h3>How to verify</h3>
                <p>{scenario.command}</p>
              </article>
            </section>
          )
        )}

        {hasChatChangedFilesList(scenario) && scenario.workedForLabel ? (
          <>
            <div className="ai-chat-edited-files-worked-for">{`Worked for ${scenario.workedForLabel}`}</div>
            <ChatEditedFilesCard
              files={getChatChangeCards(scenario)}
              onOpenFile={onOpenChangedFile}
              onOpenReview={onOpenDiffTab ? () => {
                const firstDiffRequest = getChatChangeCards(scenario)
                  .map((card) => card?.diffRequest)
                  .find(Boolean);
                if (firstDiffRequest) onOpenDiffTab(firstDiffRequest);
              } : null}
            />
            <hr className="ai-chat-edited-files-divider" />
          </>
        ) : null}

        {sentMessages.map((message) => (
          message.kind === 'review-command' ? null : message.role === 'assistant' && message.kind === 'review-summary' ? (
            <ReviewSummaryMessage
              key={message.id}
              summary={message.reviewSummary}
              agentIcon={selectedAgent.id}
              lifecycleStatus={agentRun?.status ?? 'open'}
              reviewFiles={reviewFiles}
              onOpenReview={() => onOpenReviewDiff?.(chatId)}
              onFileCommentsChange={onReviewFileCommentsChange}
              onApplyFile={onApplyReviewFile}
              onDismissFile={onDismissReviewFile}
              readOnly={isReviewFinal}
            />
          ) : message.role === 'assistant'
            && message.streaming
            && agentRun?.kind === 'review' ? (
            <div key={message.id} className="aiux550-review-running" role="status" aria-label="Review running">
              <AiChatProgressIcon />
              <span>Running...</span>
            </div>
          ) : message.role === 'assistant'
            && (message.kind === 'sdd-spec-generated' || message.kind === 'sdd-status')
            && message.streaming ? (
            message.kind === 'sdd-spec-generated' && message.prompt
              ? <SddSpecGenerationStreamingMessage key={message.id} message={message} />
              : (
                // Same no-heading treatment as the finished reply below — the
                // agent-name heading (e.g. "SDD") only ever showed up here while
                // the text was still streaming in, which read as inconsistent.
                <article key={message.id} className="aiux543-answer">
                  <p
                    data-ai-chat-annotatable="true"
                    data-ai-chat-message-id={message.id}
                    data-ai-chat-block-id={`sent-${message.id}`}
                  >
                    {renderAnnotatedParagraph(message.text, `sent-${message.id}`, message.id)}
                    <span className="ai-chat-streaming-caret" aria-hidden="true" />
                  </p>
                </article>
              )
          ) : message.role === 'assistant' && message.kind === 'sdd-status' && !message.streaming ? (
            // Plain no-heading text once done streaming too — this is just a
            // transient "running the checks" status line, not a reply with
            // its own agent-name heading.
            <article key={message.id} className="aiux543-answer">
              <p
                data-ai-chat-annotatable="true"
                data-ai-chat-message-id={message.id}
                data-ai-chat-block-id={`sent-${message.id}`}
              >
                {renderAnnotatedParagraph(message.text, `sent-${message.id}`, message.id)}
              </p>
            </article>
          ) : message.role === 'assistant' && message.kind === 'sdd-spec-generated' && !message.streaming ? (
            <Fragment key={message.id}>
              {Array.isArray(message.result) && message.result.length > 0 && (
                <ul className="aiux543-answer-result-list">
                  {message.result.map((paragraph, idx) => (
                    <li
                      key={`sdd-result-${message.id}-${idx}`}
                      data-ai-chat-annotatable="true"
                      data-ai-chat-message-id={message.id}
                      data-ai-chat-block-id={`sdd-result-${idx}`}
                    >
                      {renderAnnotatedParagraph(paragraph, `sdd-result-${idx}`, message.id)}
                    </li>
                  ))}
                </ul>
              )}
              <ChatEditedFilesSummary
                files={message.changeCards ?? []}
                workedForLabel={message.workedForLabel}
                // Opens the generated spec as its own editor tab. Split view
                // (openCommentTarget → openSpecInSplitView) is deliberately
                // skipped here for now — revisit later.
                onOpenFile={(file) => (file.agentTaskId ? onOpenAgentTaskTab?.(file.agentTaskId) : onOpenChangedFile?.(file))}
              />
            </Fragment>
          ) : message.role === 'assistant' && message.kind === 'sdd-build-completed' && !message.streaming ? (
            <Fragment key={message.id}>
              <ChatEditedFilesSummary
                files={message.changeCards ?? []}
                workedForLabel={message.workedForLabel}
                onOpenFile={(file) => (file.agentTaskId ? onOpenAgentTaskTab?.(file.agentTaskId) : onOpenChangedFile?.(file))}
              />
            </Fragment>
          ) : message.role === 'assistant' ? (
            <article key={message.id} className="aiux543-answer">
              <h3>{selectedAgent.buttonLabel ?? selectedAgent.label}</h3>
              <p
                data-ai-chat-annotatable="true"
                data-ai-chat-message-id={message.id}
                data-ai-chat-block-id={`sent-${message.id}`}
              >
                {renderAnnotatedParagraph(message.text, `sent-${message.id}`, message.id)}
                {message.streaming ? <span className="ai-chat-streaming-caret" aria-hidden="true" /> : null}
              </p>
            </article>
          ) : (
            <ChatUserCard
              key={message.id}
              messageId={message.id}
              attachments={message.attachments}
              attachmentsFirst={Boolean(message.attachmentsFirst)}
              contentParts={message.contentParts}
              onAttachmentOpen={(attachment) => {
                if (onOpenAttachment) {
                  onOpenAttachment(attachment, { messageId: message.id, chatId, archived: true });
                  return;
                }
                if (attachment?.diffRequest) onOpenDiffTab?.(attachment.diffRequest);
              }}
            >
              {message.text}
            </ChatUserCard>
          )
        ))}
      </div>

      <div className={`aiux543-composer-sticky${isAgentRunProcessing ? ' is-agent-running' : ''}${isNewSessionState ? ' is-new-session' : ''}`}>
        {false && showCodeReviewPrompt && reviewPromptFiles.length > 0 && (
          <CodeReviewComposerPrompt
            onCreateSpec={onCreateSpec}
            onRunReview={() => onRunCodeReview?.(chatId)}
            onCommitChanges={() => onCommitChanges?.(chatId)}
          />
        )}
        {isNewSessionState && (
          <div className="aiux543-new-session-agent-picker" ref={agentPickerRef}>
            <button
              type="button"
              className={`aiux543-new-session-agent-trigger${isAgentMenuOpen ? ' is-open' : ''}`}
              aria-label={`Agent: ${selectedAgent.label}`}
              aria-haspopup="menu"
              aria-expanded={isAgentMenuOpen}
              onClick={() => setIsAgentMenuOpen((open) => !open)}
            >
              <FinalToolbarSessionPresetIcon agentId={selectedAgent.id} />
              <span>{selectedAgent.buttonLabel ?? selectedAgent.label}</span>
              <Icon name="general/chevronDown" size={16} />
            </button>
            {isAgentMenuOpen && (
              <div className="aiux543-new-session-agent-menu" role="menu" aria-label="Choose agent">
                <div className="aiux543-new-session-agent-menu-label">Agents</div>
                {AI_CHAT_AGENTS.map((agent) => (
                  <button
                    type="button"
                    role="menuitemradio"
                    aria-checked={selectedAgentId === agent.id}
                    className={`aiux543-new-session-agent-option${selectedAgentId === agent.id ? ' is-selected' : ''}`}
                    key={agent.id}
                    onClick={() => {
                      setSelectedAgentId(agent.id);
                      setSelectedModelOverride(null);
                      setSelectedEffort(CODEX_STYLE_AGENT_IDS.includes(agent.id) ? 'Extra High' : 'Medium effort');
                      setIsAgentMenuOpen(false);
                      onAgentChange?.(chatId, agent.id);
                      requestAnimationFrame(() => composerRef.current?.focus());
                    }}
                  >
                    <span className="aiux543-new-session-agent-option-icon">
                      <FinalToolbarSessionPresetIcon agentId={agent.id} />
                    </span>
                    <span className="aiux543-new-session-agent-option-copy">
                      <strong>{agent.label}</strong>
                    </span>
                    {agent.badge && <span className="aiux543-new-session-agent-badge">{agent.badge}</span>}
                    {selectedAgentId === agent.id && <Icon name="general/checkmark" size={16} />}
                  </button>
                ))}
                <div className="aiux543-new-session-agent-menu-separator" />
                <button type="button" role="menuitem" className="aiux543-new-session-agent-action">
                  <Icon name="general/add" size={18} />
                  <span>Add More Agents...</span>
                </button>
                <button type="button" role="menuitem" className="aiux543-new-session-agent-action">
                  <Icon name="general/settings" size={18} />
                  <span>Agent Settings...</span>
                </button>
              </div>
            )}
          </div>
        )}
        {/* Hidden for now — the "Local" scope block will be reintroduced later. */}
        {false && (
          <div className="aiux543-chat-local-card">
            <button type="button" className="aiux543-chat-dropdown">
              <span>Local</span>
              <Icon name="general/chevronDown" size={16} />
            </button>
          </div>
        )}
        {!isReviewDecisionReady && isAgentRunProcessing && (
          <ComposerFollowUpQueue
            items={queuedFollowUps}
            scopeItems={reviewScopeQueueItems}
            onDeleteItem={(itemId) => setQueuedFollowUps((items) => items.filter((item) => item.id !== itemId))}
            onReorderItems={setQueuedFollowUps}
            onSendNowItem={(itemId) => setQueuedFollowUps((items) => items.filter((item) => item.id !== itemId))}
            revealSendNowOnHover
          />
        )}
        {!isReviewDecisionReady && (
        <div className={`aiux543-chat-composer${isNewSessionComposerExpanded ? ' is-expanded' : ''}`} onClick={() => composerRef.current?.focus()}>
          {showSlashCommandMenu && (
            <div className="aiux543-slash-command-menu" role="listbox" aria-label="Slash commands">
              <div className="aiux543-slash-command-list">
                {filteredSlashCommands.map((item, index) => (
                  <button
                    key={item.command}
                    type="button"
                    role="option"
                    aria-selected={index === activeSlashCommandIndex}
                    className={`aiux543-slash-command-item${index === activeSlashCommandIndex ? ' is-selected' : ''}`}
                    onMouseDown={(event) => event.preventDefault()}
                    onClick={(event) => {
                      event.stopPropagation();
                      insertSlashCommand(item.command);
                    }}
                  >
                    <span className="aiux543-slash-command-name">{item.command}</span>
                    <span className="aiux543-slash-command-description">{item.description}</span>
                  </button>
                ))}
              </div>
              <div className="aiux543-slash-command-footer">
                <span>Press ↵ to insert, ↑↓ to navigate</span>
                <span>Esc to close</span>
              </div>
            </div>
          )}
          {isNewSessionState && (
            <button
              type="button"
              className="aiux543-new-session-expand"
              aria-label={isNewSessionComposerExpanded ? 'Collapse input' : 'Expand input'}
              aria-pressed={isNewSessionComposerExpanded}
              onClick={(event) => {
                event.stopPropagation();
                setIsNewSessionComposerExpanded((expanded) => !expanded);
                requestAnimationFrame(() => composerRef.current?.focus());
              }}
            >
              <Icon name={isNewSessionComposerExpanded ? 'inline/collapse' : 'inline/expand'} size={16} />
            </button>
          )}
          <div className="aiux543-chat-input-row ai-chat-inline-input-content">
            {orderedComposerParts.map((part) => (
              part.type === 'text'
                ? <span key={part.id} className="ai-chat-composer-text-segment">{part.text}</span>
                : renderComposerAttachment(composerAttachmentById.get(part.attachmentId), part.id)
            ))}
            <textarea
              ref={composerRef}
              className="aiux543-chat-input"
              rows={1}
              value={composerText}
              placeholder={orderedComposerParts.length > 0
                ? ''
                : isAgentRunProcessing
                  ? 'Add a follow-up'
                  : isReviewFeedbackMode
                    ? 'Add feedback for the next review iteration'
                    : 'Type task, use @mentions or /commands'}
              aria-label={isAgentRunProcessing ? 'Add a follow-up' : 'Task prompt'}
              onChange={(event) => {
                setComposerText(event.target.value);
                setSlashCommandIndex(0);
                setSlashCommandMenuDismissed(false);
              }}
              onKeyDown={(event) => {
                if (handleComposerBackspace(event)) return;
                if (isReviewFeedbackMode && event.key === 'Escape') {
                  event.preventDefault();
                  setReviewFeedbackMessageId(null);
                  setResolvedReviewDecisionId(null);
                  return;
                }
                if (showSlashCommandMenu) {
                  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                    event.preventDefault();
                    const direction = event.key === 'ArrowDown' ? 1 : -1;
                    setSlashCommandIndex((index) => (
                      (index + direction + filteredSlashCommands.length) % filteredSlashCommands.length
                    ));
                    return;
                  }
                  if (event.key === 'Escape') {
                    event.preventDefault();
                    setSlashCommandMenuDismissed(true);
                    return;
                  }
                  if (event.key === 'Enter' || event.key === 'Tab') {
                    event.preventDefault();
                    insertSlashCommand(filteredSlashCommands[activeSlashCommandIndex].command);
                    return;
                  }
                }
                if (event.key === 'Enter' && !event.shiftKey) {
                  event.preventDefault();
                  handleSend();
                }
              }}
            />
          </div>
          <div className="aiux543-chat-toolbar">
            <div className="aiux543-chat-toolbar-left">
              <button
                className={`aiux543-chat-icon-button${showNewContextOptionsIndicator && !isAgentRunProcessing ? ' has-new-context-options' : ''}`}
                type="button"
                aria-label="Add context"
                aria-expanded={Boolean(addContextPopupRect)}
                onClick={(event) => {
                  const rect = event.currentTarget.getBoundingClientRect();
                  if (addContextPopupRect) {
                    setAddContextPopupRect(null);
                  } else {
                    onAddContextPopupOpen?.();
                    setAddContextPopupRect(rect);
                  }
                }}
              >
                <Icon name="general/add" size={16} />
              </button>
            </div>
            <div className="aiux543-chat-toolbar-right">
              {isAgentRunProcessing ? (
                <>
                  <button type="button" className="aiux543-chat-icon-button" aria-label="Voice input">
                    <AiChatMicIcon />
                  </button>
                  <button
                    type="button"
                    className="aiux543-chat-icon-button aiux543-chat-stop-button"
                    aria-label="Stop"
                    onClick={() => onStopMessage?.(chatId)}
                  >
                    <span className="aiux543-chat-stop-square" aria-hidden="true" />
                  </button>
                </>
              ) : (
                <>
                  <button type="button" className="aiux543-chat-icon-button" aria-label="Generating">
                    <AiChatProgressIcon />
                  </button>
                  <button
                    type="button"
                    className="aiux543-chat-icon-button"
                    aria-label={isReviewFeedbackMode ? 'Submit Review' : 'Send'}
                    onClick={handleSend}
                    disabled={!canSend}
                  >
                    <AiChatSendIcon />
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
        )}
        {isReviewDecisionReady ? (
          <ReviewDecisionComposer
            onSkip={() => {
              setReviewFeedbackMessageId(null);
              setResolvedReviewDecisionId(readyReviewMessage.id);
              focusComposerAtEnd();
            }}
            onSubmit={() => {
              if (hasReviewFeedbackBatch) {
                sendReviewFeedback(composerText.trim(), [
                  ...composerContentParts,
                  ...(composerText.trim().length > 0
                    ? [{ id: 'live-text', type: 'text', text: composerText }]
                    : []),
                ]);
                return;
              }
              setReviewFeedbackMessageId(readyReviewMessage.id);
              setResolvedReviewDecisionId(readyReviewMessage.id);
              focusComposerAtEnd();
            }}
            onCancel={() => {
              setReviewFeedbackMessageId(null);
              setResolvedReviewDecisionId(readyReviewMessage.id);
              onCancelReview?.(chatId);
              focusComposerAtEnd();
            }}
            onComplete={() => {
              setReviewFeedbackMessageId(null);
              setResolvedReviewDecisionId(readyReviewMessage.id);
              onCompleteReview?.(chatId);
              focusComposerAtEnd();
            }}
          />
        ) : isNewSessionState || isAgentRunProcessing ? (
          <footer
            className={`aiux543-editor-footer aiux543-new-session-settings${isAgentRunProcessing ? ' aiux543-chat-session-settings' : ''}`}
            ref={newSessionSettingsRef}
          >
            <span className="aiux543-editor-footer-left">
              <NewSessionFooterPicker
                id="model"
                label={selectedModelLabel}
                options={newSessionModelOptions}
                open={newSessionSettingsMenu === 'model'}
                onOpenChange={setNewSessionSettingsMenu}
                onSelect={(model) => setSelectedModelOverride(model === selectedAgent.model ? null : model)}
              />
              <NewSessionFooterPicker
                id="effort"
                label={selectedEffort}
                options={composerEffortOptions}
                open={newSessionSettingsMenu === 'effort'}
                onOpenChange={setNewSessionSettingsMenu}
                onSelect={setSelectedEffort}
              />
              {isCodexStyleAgent ? (
                <>
                  <NewSessionFooterPicker
                    id="mode"
                    label="Agent"
                    options={['Agent']}
                    open={newSessionSettingsMenu === 'mode'}
                    onOpenChange={setNewSessionSettingsMenu}
                    onSelect={() => {}}
                  />
                  <NewSessionFooterPicker
                    id="fast-mode"
                    label="Fast mode · Off"
                    options={['Fast mode · Off']}
                    open={newSessionSettingsMenu === 'fast-mode'}
                    onOpenChange={setNewSessionSettingsMenu}
                    onSelect={() => {}}
                  />
                  <NewSessionFooterPicker
                    id="sdd-mode"
                    label={sddModeOn ? 'SDD mode: On' : 'SDD mode: Off'}
                    options={['SDD mode: On', 'SDD mode: Off']}
                    open={newSessionSettingsMenu === 'sdd-mode'}
                    onOpenChange={setNewSessionSettingsMenu}
                    onSelect={(option) => setSddModeOn(option === 'SDD mode: On')}
                  />
                </>
              ) : (
                <NewSessionFooterPicker
                  id="access"
                  label={selectedAccess}
                  options={['Read only', 'Ask before changes', 'Full access']}
                  open={newSessionSettingsMenu === 'access'}
                  onOpenChange={setNewSessionSettingsMenu}
                  onSelect={setSelectedAccess}
                />
              )}
            </span>
            {isAgentRunProcessing && !isCodexStyleAgent && <span>Feedback <Icon name="ide/externalLink" size={16} /></span>}
          </footer>
        ) : (
          <footer className="aiux543-editor-footer aiux543-new-session-settings aiux543-chat-session-settings" ref={newSessionSettingsRef}>
            <span className="aiux543-editor-footer-left">
              {!isCodexStyleAgent && (
                <NewSessionFooterPicker
                  id="edit-mode"
                  label={selectedEditMode}
                  options={['Accepts Edits', 'Ask Before Edits', 'Read Only']}
                  open={newSessionSettingsMenu === 'edit-mode'}
                  onOpenChange={setNewSessionSettingsMenu}
                  onSelect={setSelectedEditMode}
                />
              )}
              <NewSessionFooterPicker
                id="chat-model"
                label={selectedModelLabel}
                options={chatModelOptions}
                open={newSessionSettingsMenu === 'chat-model'}
                onOpenChange={setNewSessionSettingsMenu}
                onSelect={(model) => setSelectedModelOverride(model === selectedAgent.model ? null : model)}
              />
              <NewSessionFooterPicker
                id="chat-effort"
                label={selectedEffort}
                options={composerEffortOptions}
                open={newSessionSettingsMenu === 'chat-effort'}
                onOpenChange={setNewSessionSettingsMenu}
                onSelect={setSelectedEffort}
              />
              {isCodexStyleAgent && (
                <>
                  <NewSessionFooterPicker
                    id="chat-mode"
                    label="Agent"
                    options={['Agent']}
                    open={newSessionSettingsMenu === 'chat-mode'}
                    onOpenChange={setNewSessionSettingsMenu}
                    onSelect={() => {}}
                  />
                  <NewSessionFooterPicker
                    id="chat-fast-mode"
                    label="Fast mode · Off"
                    options={['Fast mode · Off']}
                    open={newSessionSettingsMenu === 'chat-fast-mode'}
                    onOpenChange={setNewSessionSettingsMenu}
                    onSelect={() => {}}
                  />
                  <NewSessionFooterPicker
                    id="chat-sdd-mode"
                    label={sddModeOn ? 'SDD mode: On' : 'SDD mode: Off'}
                    options={['SDD mode: On', 'SDD mode: Off']}
                    open={newSessionSettingsMenu === 'chat-sdd-mode'}
                    onOpenChange={setNewSessionSettingsMenu}
                    onSelect={(option) => setSddModeOn(option === 'SDD mode: On')}
                  />
                </>
              )}
            </span>
            {!isCodexStyleAgent && <span>Feedback <Icon name="ide/externalLink" size={16} /></span>}
          </footer>
        )}
        <AiChatAttachmentContextMenu
          menu={composerAttachmentContextMenu}
          onClose={() => setComposerAttachmentContextMenu(null)}
          onOpenInFiles={handleComposerAttachmentOpen}
          onClearAll={handleClearAllComposerAttachmentsFromMenu}
        />
      </div>
      {addContextPopupRect && (
        <AiChatAddContextPopup
          triggerRect={addContextPopupRect}
          onDismiss={() => setAddContextPopupRect(null)}
          plainFileGutterCommentsEnabled={plainFileGutterCommentsEnabled}
          onPlainFileGutterCommentsEnabledChange={onPlainFileGutterCommentsEnabledChange}
          diffGutterCommentsEnabled={diffGutterCommentsEnabled}
          onDiffGutterCommentsEnabledChange={onDiffGutterCommentsEnabledChange}
          fileCommentsOptionIsNew={fileCommentsOptionIsNew}
          diffCommentsOptionIsNew={diffCommentsOptionIsNew}
          onFileCommentsOptionSeen={onFileCommentsOptionSeen}
          onDiffCommentsOptionSeen={onDiffCommentsOptionSeen}
        />
      )}
    </div>
  );
}

